import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': failed_files}
    if not os.path.exists(dst_folder):
        os.makedirs(dst_folder)
    files = glob(os.path.join(src_folder, '*'))
    for file_path in files:
        try:
            if os.path.isfile(file_path):
                subprocess.run(['gzip', file_path], check=True, capture_output=True)
                gz_file = file_path + '.gz'
                if os.path.exists(gz_file):
                    shutil.move(gz_file, dst_folder)
        except Exception:
            failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else f'{len(failed_files)} file(s) failed to process'
    return {'success': success, 'message': message, 'failed_files': failed_files}

