import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError("Script path does not exist")
    cpu_usage = 0.0
    mem_usage = 0
    process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    start_time = time.time()
    try:
        while True:
            if time.time() - start_time > timeout:
                process.terminate()
                process.wait()
                break
            try:
                p = psutil.Process(process.pid)
                cpu_usage += p.cpu_percent(interval=0.1)
                mem_usage += p.memory_info().rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            if process.poll() is not None:
                break
    finally:
        if process.poll() is None:
            process.kill()
            process.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

